 /** Supported languages, the first is the fallback. */
 export const LANGUAGES = Object.keys(MESSAGES);

+/** Picks a supported language from an `Accept-Language` header, falling back to `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  const raw = Array.isArray(header) ? header.join(",") : header;
+  if (typeof raw !== "string" || !raw.trim()) return fallback;
+  const candidates = [];
+  for (const part of raw.split(",")) {
+    const [tag, ...params] = part.trim().split(";");
+    if (!tag) continue;
+    const lang = tag.trim().split("-")[0].toLowerCase();
+    if (!LANGUAGES.includes(lang)) continue;
+    let q = 1;
+    for (const p of params) {
+      if (!p.trim()) continue;
+      const [k, v] = p.split("=").map((s) => s.trim());
+      if (k.toLowerCase() === "q") q = v === "" ? NaN : Number(v);
+    }
+    if (!Number.isFinite(q) || q <= 0 || q > 1) continue;
+    candidates.push({ lang, q });
+  }
+  if (!candidates.length) return fallback;
+  candidates.sort((a, b) => b.q - a.q);
+  return candidates[0].lang;
+}
